function CardProgressionEquipmentPresetSuitCell:RefreshCell(conf, index, isSelected, cb)
    self._tabConf = conf
    self._index = index
    self._cb = cb

    CfUtils.FillText(self.TextDesc, conf.name)
    CfUtils.SetActive(self.ImgSelect, isSelected)

    local equipmentList = string.split(conf.equipments, ",")
    for i = 1, CardProgressionConstants.EquipmentNum do
        local equipGo = self.EquippingTankItem:Find(string.format('BtnTankGroup%d', i))
        local scr = CfUtils.GetLuaScr(equipGo, "Game.CardProgression.Equip.CardProgressionCardEquipBtnNode")
        if scr then
            local equipmentId = equipmentList[i]
            local equipDojo = EquipComponent:GetEquipById(equipmentId)
            scr:RefreshUI(equipDojo)
        end
    end
end
